"""Provided HMM models and validation. Do not edit this file."""
from dataclasses import dataclass
from math import isclose, isfinite


@dataclass
class HMM:
    states: list[str]
    symbols: list[str]
    prior: list[float]
    transition: list[list[float]]
    sensor: list[list[float]]

    def validate(self):
        n, m = len(self.states), len(self.symbols)
        if n < 1 or m < 1 or len(set(self.states)) != n or len(set(self.symbols)) != m:
            raise ValueError("State and observation labels must be nonempty and unique")
        if len(self.prior) != n or len(self.transition) != n or len(self.sensor) != n:
            raise ValueError("Model dimensions do not match labels")
        for row, size in [(self.prior, n)] + [(r, n) for r in self.transition] + [(r, m) for r in self.sensor]:
            if len(row) != size or any(not isfinite(v) or v < 0 for v in row):
                raise ValueError("Probability row has invalid dimensions or entries")
            if not isclose(sum(row), 1.0, rel_tol=0, abs_tol=1e-12):
                raise ValueError("Each probability row must sum to one")
        return self


def get_model(name="umbrella"):
    """Return a fresh model; U=0, N=1 for every weather model.

    sensor rows contain [P(U|state), P(N|state)]. These are teaching models,
    not fitted weather forecasts. Only one model component changes in each
    controlled comparison.
    """
    if name == "three_state":
        return HMM(
            ["Dry", "Cloudy", "Rain"], ["U", "N"], [.6, .3, .1],
            [[.75, .20, .05], [.20, .60, .20], [.10, .30, .60]],
            [[.10, .90], [.40, .60], [.85, .15]],
        ).validate()
    if name not in ("umbrella", "reliable", "noisy", "persistent", "weak"):
        raise ValueError(f"Unknown model: {name}")
    transition = [[.7, .3], [.3, .7]]
    sensor = [[.9, .1], [.2, .8]]
    if name == "reliable":
        sensor = [[.95, .05], [.05, .95]]
    elif name == "noisy":
        sensor = [[.60, .40], [.40, .60]]
    elif name == "persistent":
        transition = [[.90, .10], [.10, .90]]
    elif name == "weak":
        transition = [[.55, .45], [.45, .55]]
    return HMM(["Rain", "NoRain"], ["U", "N"], [.5, .5], transition, sensor).validate()


